package com.wipro.hibernate;import org.hibernate.*;public class Main{public static void main(String[]a){try(Session s=HibernateUtil.getSessionFactory().openSession()){Transaction t=s.beginTransaction();s.persist(new CarDetail("KL-07","AB 123 Polo","White","Volkswagen"));t.commit();System.out.println("Car mapping and insert successful.");}HibernateUtil.getSessionFactory().close();}}